const item = $input.first().json;
const headers = item.headers || {};
const body = item.body && typeof item.body === 'object' ? item.body : {};
const errors = [];
const ct = String(headers['content-type'] || '').toLowerCase();
if (ct.indexOf('application/json') === -1) errors.push('Content-Type must be application/json');
const clean = (v) => (typeof v === 'string' ? v.trim() : '');
const num = (x) => { const n = Number(String(x === null || x === undefined ? '' : x).replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const author_id = clean(body.author_id);
const request_id = clean(body.request_id);
const triggered_by = clean(body.triggered_by);
const author_name = clean(body.author_name);
const author_email = clean(body.author_email);
if (!author_id) errors.push('author_id is required');
if (!request_id) errors.push('request_id is required');
if (!triggered_by) errors.push('triggered_by is required');
if (!author_name) errors.push('author_name is required');
if (!author_email) errors.push('author_email is required');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(author_email)) errors.push('author_email is not a valid email address');
const books = [];
const raw = clean(body.books_summary);
if (!raw) errors.push('books_summary is required');
else {
  raw.split('##').forEach((rec) => {
    const f = rec.split('||').map((s) => s.trim());
    if (f.length < 8 || !f[0]) { if (errors.indexOf('books_summary has a malformed book entry') === -1) errors.push('books_summary has a malformed book entry'); return; }
    books.push({ title: f[0], copies: num(f[1]), earned: num(f[2]), paid: num(f[3]), pending: num(f[4]), royalty_status: f[5], publication_status: f[6], last_payout: f[7] });
  });
}
return [{ json: { valid: errors.length === 0, errors: errors, error_message: 'Invalid request: ' + errors.join('; '), request_id: request_id, author_id: author_id, triggered_by: triggered_by, author_name: author_name, author_email: author_email, environment: clean(body.environment) || 'development', books: books, bubble_totals: { earned: num(body.total_earned), paid: num(body.total_paid), pending: num(body.total_pending) }, bubble_royalty_status: clean(body.royalty_status), last_payout_date: clean(body.last_payout_date), received_at: new Date().toISOString() } }];

const v = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.requests = sd.requests || {};
sd.authors = sd.authors || {};
const now = Date.now();
const DAY = 86400000;
const LOCK = 10 * 60 * 1000;
Object.keys(sd.requests).forEach((k) => { if (now - sd.requests[k].ts > 30 * DAY) delete sd.requests[k]; });
Object.keys(sd.authors).forEach((k) => { if (now - sd.authors[k].ts > LOCK) delete sd.authors[k]; });
const prior = sd.requests[v.request_id];
const lock = sd.authors[v.author_id];
let duplicate = false;
let reason = '';
if (prior && prior.status === 'success') { duplicate = true; reason = 'Request already completed successfully.'; }
else if (prior && prior.status === 'processing' && now - prior.ts < LOCK) { duplicate = true; reason = 'Request is already being processed.'; }
else if (lock && lock.request_id !== v.request_id) { duplicate = true; reason = 'Another summary for this author is already being processed.'; }
if (!duplicate) {
  sd.requests[v.request_id] = { status: 'processing', ts: now, author_id: v.author_id };
  sd.authors[v.author_id] = { request_id: v.request_id, ts: now };
}
return [{ json: Object.assign({}, v, { is_duplicate: duplicate, duplicate_reason: reason }) }];

const v = $input.first().json;
const books = v.books.map((b, i) => ({
  book_id: 'book-' + (i + 1),
  title: b.title,
  status: b.publication_status,
  publication_date: null,
  total_copies_sold: b.copies,
  total_royalty_earned: b.earned,
  royalty_paid: b.paid,
  royalty_pending: b.pending,
  last_royalty_payout_date: b.last_payout || null
}));
const isPublished = (b) => String(b.status || '').trim().toLowerCase().indexOf('published') === 0;
return [{ json: {
  request_id: v.request_id,
  triggered_by: v.triggered_by,
  environment: v.environment,
  author: { author_id: v.author_id, name: v.author_name, email: v.author_email },
  bubble_totals: v.bubble_totals,
  bubble_royalty_status: v.bubble_royalty_status,
  published_books: books.filter(isPublished),
  production_books: books.filter((b) => !isPublished(b)),
  total_books: books.length
} }];

const d = $input.first().json;
const num = (x) => {
  if (x === null || x === undefined || x === '') return 0;
  const n = Number(String(x).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? 0 : n;
};
const round2 = (n) => Math.round(n * 100) / 100;
const all = d.published_books.concat(d.production_books);
let earned = 0;
let paid = 0;
let pending = 0;
let copies = 0;
let latest = null;
all.forEach((b) => {
  earned += num(b.total_royalty_earned);
  paid += num(b.royalty_paid);
  pending += num(b.royalty_pending);
  if (b.last_royalty_payout_date) {
    const t = new Date(b.last_royalty_payout_date).getTime();
    if (!isNaN(t) && (latest === null || t > latest)) latest = t;
  }
});
d.published_books.forEach((b) => {
  copies += num(b.total_copies_sold);
});
return [{ json: Object.assign({}, d, {
  totals: {
    total_royalty_earned: round2(earned),
    total_royalty_paid: round2(paid),
    total_royalty_pending: round2(pending),
    total_copies_sold: copies,
    latest_payout_date: latest === null ? null : new Date(latest).toISOString()
  }
}) }];

const d = $input.first().json;
const DAY = 86400000;
const now = Date.now();
const pending = d.totals.total_royalty_pending;
const bs = String(d.bubble_royalty_status || '').trim().toLowerCase();
let status = 'FULLY PAID';
const reasons = [];
if (pending > 0) {
  status = 'PENDING';
  if (bs === 'overdue') reasons.push('Marked overdue in BookLeaf records');
  if (d.totals.latest_payout_date) {
    const days = (now - new Date(d.totals.latest_payout_date).getTime()) / DAY;
    if (days > 90) reasons.push('Latest payout was more than 90 days ago');
  }
  if (reasons.length) status = 'OVERDUE';
}
const t = new Date(now);
const y = t.getUTCFullYear();
const qs = Math.floor(t.getUTCMonth() / 3) * 3;
const prevQEnd = new Date(Date.UTC(y, qs, 0));
const curQEnd = new Date(Date.UTC(y, qs + 3, 0));
let due = new Date(prevQEnd.getTime() + 45 * DAY);
if (now > due.getTime()) due = new Date(curQEnd.getTime() + 45 * DAY);
const payout_info = {
  last_payout_date: d.totals.latest_payout_date ? d.totals.latest_payout_date.slice(0, 10) : null,
  next_payout_expected_by: due.toISOString().slice(0, 10),
  minimum_payout_threshold: 1000,
  pending_below_threshold: pending > 0 && pending < 1000
};
const fmt = (b) => ({
  title: b.title,
  copies_sold: b.total_copies_sold,
  royalty_earned: b.total_royalty_earned,
  royalty_paid: b.royalty_paid,
  royalty_pending: b.royalty_pending,
  last_payout_date: b.last_royalty_payout_date
});
return [{ json: Object.assign({}, d, {
  royalty_status: status,
  status_reasons: reasons,
  payout_info: payout_info,
  ai_input: {
    author_name: d.author.name,
    royalty_status: status,
    published_books: d.published_books.map(fmt),
    books_in_production: d.production_books.map((b) => ({ title: b.title, production_status: b.status })),
    totals: d.totals,
    payout_info: payout_info
  }
}) }];

