const j = $input.first().json || {};
const ctx = $('Check Royalty Status').first().json;
const text = typeof j.text === 'string' ? j.text.trim() : '';
const fullName = String(ctx.author.name || '').trim();
const firstName = fullName.split(' ')[0].toLowerCase();
const lower = text.toLowerCase();
let error = '';
if (j.error) {
  error = 'OpenAI generation failed: ' + (j.error.message || j.error);
} else if (!text) {
  error = 'OpenAI returned an empty summary';
} else if (text.length < 200) {
  error = 'OpenAI summary is too short to be valid';
} else if (firstName && lower.indexOf(firstName) === -1) {
  error = 'OpenAI summary does not contain the author name';
} else if (lower.indexOf('subject:') === -1) {
  error = 'OpenAI summary is missing the subject line';
} else if (['error:', 'i\'m sorry', 'i cannot', 'i can\'t', 'as an ai'].some((p) => lower.indexOf(p) === 0 || lower.indexOf('as an ai') !== -1)) {
  error = 'OpenAI response looks like an error or refusal message';
}
return [{ json: {
  valid: error === '',
  error_message: error,
  request_id: ctx.request_id,
  author_name: fullName,
  generated_summary: error === '' ? text : ''
} }];

const ctx = $('Check Royalty Status').first().json;
const ai = $('Validate AI Response').first().json;
const cfg = $('Workflow Config').first().json;
const esc = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cell = (v, right, bold) => '<td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:14px;color:#111827;' + (right ? 'text-align:right;' : '') + (bold ? 'font-weight:700;' : '') + '">' + v + '</td>';
const head = (v, right) => '<th style="padding:10px 12px;background:#f9fafb;border-bottom:2px solid #e5e7eb;font-size:12px;color:#6b7280;text-transform:uppercase;' + (right ? 'text-align:right;' : 'text-align:left;') + '">' + v + '</th>';
const t = ctx.totals;
const p = ctx.payout_info;
const books = ctx.published_books.concat(ctx.production_books);
const rows = books.map((b) => '<tr>' + cell(esc(b.title) + '<div style="color:#6b7280;font-size:12px">' + esc(b.status) + '</div>') + cell(esc(b.total_copies_sold), true) + cell(inr(b.total_royalty_earned), true) + cell(inr(b.royalty_paid), true) + cell(inr(b.royalty_pending), true) + '</tr>').join('');
const body = String(ai.generated_summary || '').replace(/^\s*subject:[^\n]*\n+/i, '');
const narrative = esc(body).split('\n').map((l0) => {
  let l = l0.trim();
  if (!l) return '';
  l = l.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  const h = l.match(/^#{1,6}\s+(.*)$/);
  if (h) return '<div style="font-weight:700;margin:14px 0 4px;color:#111827">' + h[1] + '</div>';
  if (/^[-*]\s+/.test(l)) return '<div style="margin-left:12px">&bull; ' + l.replace(/^[-*]\s+/, '') + '</div>';
  return '<div style="margin:6px 0">' + l + '</div>';
}).join('');
const badge = t.total_royalty_pending <= 0 ? ['Paid in full', '#065f46', '#d1fae5'] : (ctx.royalty_status === 'OVERDUE' ? ['Payout delayed', '#991b1b', '#fee2e2'] : ['Payout pending', '#92400e', '#fef3c7']);
const last = p.last_payout_date ? esc(p.last_payout_date) : 'No payout recorded yet';
const next = t.total_royalty_pending > 0 ? 'Payouts are processed within 45 days of each quarter end (current cycle deadline: ' + esc(p.next_payout_expected_by) + ')' + (p.pending_below_threshold ? '. Your balance is below the ₹1,000 minimum, so it rolls over to the next cycle.' : ', subject to the ₹1,000 minimum payout threshold.') : 'No payout pending';
const box = (label, val) => '<td style="padding:12px;background:#f9fafb;border-radius:8px;text-align:center"><div style="font-size:12px;color:#6b7280">' + label + '</div><div style="font-size:18px;font-weight:700;color:#111827">' + val + '</div></td>';
const testRecipient = String(cfg.email_test_recipient || '').trim();
const testBanner = testRecipient ? '<div style="background:#fef3c7;padding:8px 24px;font-size:12px;color:#92400e">TEST EMAIL - originally addressed to ' + esc(ctx.author.email) + '</div>' : '';
const html = '<!DOCTYPE html><html><body style="margin:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif"><div style="max-width:640px;margin:0 auto;background:#ffffff"><div style="background:#1f3a5f;padding:24px;color:#ffffff;font-size:20px;font-weight:700">BookLeaf Publishing</div>' + testBanner + '<div style="padding:24px"><p style="font-size:16px;color:#111827">Hello ' + esc(String(ctx.author.name || '').split(' ')[0]) + ',</p><span style="display:inline-block;padding:4px 10px;border-radius:12px;font-size:12px;font-weight:700;color:' + badge[1] + ';background:' + badge[2] + '">' + badge[0] + '</span><table style="width:100%;border-spacing:8px;margin:12px 0"><tr>' + box('Earned', inr(t.total_royalty_earned)) + box('Paid', inr(t.total_royalty_paid)) + box('Pending', inr(t.total_royalty_pending)) + '</tr></table><table style="width:100%;border-collapse:collapse"><tr>' + head('Book') + head('Copies', true) + head('Earned', true) + head('Paid', true) + head('Pending', true) + '</tr>' + rows + '</table><p style="font-size:14px;color:#374151"><strong>Last payout:</strong> ' + last + '<br><strong>Next payout:</strong> ' + next + '</p><div style="font-size:14px;line-height:1.6;color:#374151;border-top:1px solid #e5e7eb;padding-top:16px">' + narrative + '</div></div><div style="padding:16px 24px;background:#f9fafb;font-size:12px;color:#6b7280">BookLeaf Publishing Support Team</div></div></body></html>';
const to = testRecipient || ctx.author.email;
const send_email = cfg.email_enabled === true;
const from = String(cfg.email_from || '');
const config_error = (send_email && (!from || /REPLACE_WITH/i.test(from))) ? 'Sender address (email_from) is not configured in the Workflow Config node' : '';
return [{ json: { request_id: ctx.request_id, subject: 'Your BookLeaf Royalty Summary', html: html, to: to, send_email: send_email, config_error: config_error, generated_summary: ai.generated_summary, author_name: ai.author_name } }];

const j = $input.first().json || {};
const em = $('Build Email HTML').first().json;
const ctx = $('Check Royalty Status').first().json;
const sd = $getWorkflowStaticData('global');
sd.requests = sd.requests || {};
sd.authors = sd.authors || {};
let email_status = 'skipped_test_mode';
let email_error = '';
if (em.send_email) {
  if (em.config_error) { email_status = 'failed'; email_error = em.config_error; }
  else if (j.error) { email_status = 'failed'; email_error = String((j.error && j.error.message) || j.error).slice(0, 300); }
  else { email_status = 'sent'; }
}
sd.requests[em.request_id] = email_status === 'failed' ? { status: 'failed', ts: Date.now(), reason: 'email_failed' } : { status: 'success', ts: Date.now() };
if (sd.authors[ctx.author.author_id]) delete sd.authors[ctx.author.author_id];
const bt = ctx.bubble_totals || {};
const t = ctx.totals;
const match = Math.abs((bt.earned || 0) - t.total_royalty_earned) < 0.01 && Math.abs((bt.paid || 0) - t.total_royalty_paid) < 0.01 && Math.abs((bt.pending || 0) - t.total_royalty_pending) < 0.01;
return [{ json: { status: email_status === 'failed' ? 'EmailFailed' : 'Success', request_id: em.request_id, summary: em.generated_summary, error_message: email_error ? 'Email delivery failed: ' + email_error : '', email_status: email_status, email_error: email_error, subject: em.subject, email_to: em.to, totals_match: match, completed_at: new Date().toISOString() } }];

const j = $input.first().json || {};
let rid = '';
let aid = '';
try { const v = $('Validate Request').first().json; rid = v.request_id; aid = v.author_id; } catch (e) {}
let msg = '';
if (j.error_message) { msg = j.error_message; }
else if (j.error) { const e = j.error; msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e)); if (e && e.node && e.node.name) msg = '[' + e.node.name + '] ' + msg; }
else if (j.message) { msg = j.message; }
else { msg = 'Royalty summary generation failed'; }
const sd = $getWorkflowStaticData('global');
sd.requests = sd.requests || {};
sd.authors = sd.authors || {};
if (rid) sd.requests[rid] = { status: 'failed', ts: Date.now(), reason: msg.slice(0, 200) };
if (aid && sd.authors[aid]) delete sd.authors[aid];
return [{ json: { status: 'Failed', request_id: rid || '', summary: '', error_message: msg.slice(0, 500), email_status: 'not_attempted', email_error: '', subject: '', email_to: '', totals_match: false, completed_at: new Date().toISOString() } }];
